// components/Navbar.jsx
import React from "react";
import { Link } from "react-router-dom";

const Navbar = () => {
    return (
        <nav style={{ padding: "1rem", background: "#282c34", color: "white" }}>
            <ul style={{ listStyle: "none", display: "flex", gap: "1rem" }}>
                <li><Link to="/" style={{ color: "white" }}>Home</Link></li>
                <li><Link to="/admin-dashboard" style={{ color: "white" }}>Admin</Link></li>
                <li><Link to="/user-dashboard" style={{ color: "white" }}>User</Link></li>
                <li><Link to="/login" style={{ color: "white" }}>Login</Link></li>
            </ul>
        </nav>
    );
};

export default Navbar;
